def _fits(version, low, high):
    value = tuple(version)
    if low is not None and tuple(low) > value:
        return False
    if high is not None and value >= tuple(high):
        return False
    return True


def _active(request, dep):
    feature = dep.get("feature")
    return feature is None or feature in request["config"]["features"]


def assess_selection(request, roots, selected):
    """Evaluate one complete package-to-version-or-unselected choice.

    ``roots`` is the exact root list to satisfy (for conflict probes this may be
    a subset of ``request["config"]["roots"]``).  ``selected`` maps a package ID
    to an offered version; omitted packages are unselected.
    """
    config = request["config"]
    prior = config["prior"]
    catalog = {
        package["package"]: {
            tuple(version["version"]): version for version in package["versions"]
        }
        for package in request["catalog"]
    }

    chosen = {package: tuple(version) for package, version in selected.items()}

    # Every selected package must exist and use an offered version.
    for package, version in chosen.items():
        if package not in catalog or version not in catalog[package]:
            return None

    # Every supplied root must be selected within its original interval.
    closure = set()
    for root in roots:
        package = root["package"]
        if package not in chosen or not _fits(chosen[package], root.get("min"), root.get("max")):
            return None
        closure.add(package)

    # Required dependencies extend the closure.  Peers do not pull their
    # target into the closure.
    changed = True
    while changed:
        changed = False
        for package in list(closure):
            if package not in chosen:
                return None
            version = catalog[package][chosen[package]]
            for dep in version["deps"]:
                if _active(request, dep) and dep["kind"] == "required":
                    target = dep["package"]
                    if target not in closure:
                        closure.add(target)
                        changed = True

    # No package outside the required closure may be selected.
    if set(chosen) != closure:
        return None

    # All active dependencies (required and peer) must target a selected
    # version inside the dependency's half-open interval.
    edges = []
    for package, version_tuple in sorted(chosen.items()):
        version = catalog[package][version_tuple]
        for dep in version["deps"]:
            if not _active(request, dep):
                continue
            target = dep["package"]
            if target not in chosen or not _fits(chosen[target], dep.get("min"), dep.get("max")):
                return None
            edges.append({
                "source": package,
                "target": target,
                "kind": dep["kind"],
                "feature": dep.get("feature"),
            })

    deltas = []
    for package in sorted(set(prior) | set(chosen)):
        prior_version = tuple(prior[package]) if package in prior else None
        selected_version = chosen.get(package)
        if prior_version != selected_version:
            deltas.append({
                "package": package,
                "prior": list(prior_version) if prior_version is not None else None,
                "selected": list(selected_version) if selected_version is not None else None,
            })

    freshness = sum(100 * version[0] + 10 * version[1] + version[2] for version in chosen.values())
    return {
        "active_dependencies": edges,
        "prior_deltas": deltas,
        "score": {
            "changes": len(deltas),
            "freshness": freshness,
        },
    }

def _fits(version, low, high):
    value = tuple(version)
    if low is not None and tuple(low) > value:
        return False
    if high is not None and value >= tuple(high):
        return False
    return True


def _active(request, dep):
    feature = dep.get("feature")
    return feature is None or feature in request["config"]["features"]


def _prepare(request, roots):
    config = request["config"]
    catalog = request["catalog"]
    packages = [package["package"] for package in catalog]
    order = {package: index for index, package in enumerate(packages)}

    versions = {}
    entries = {}
    active_deps = {}
    required_targets = {}
    for package in catalog:
        package_id = package["package"]
        version_list = []
        entry_map = {}
        dep_map = {}
        target_map = {}
        for item in package["versions"]:
            version = tuple(item["version"])
            version_list.append(version)
            entry_map[version] = item
            active = [dep for dep in item["deps"] if _active(request, dep)]
            dep_map[version] = [
                {
                    "package": dep["package"],
                    "min": tuple(dep["min"]) if dep.get("min") is not None else None,
                    "max": tuple(dep["max"]) if dep.get("max") is not None else None,
                    "kind": dep["kind"],
                }
                for dep in active
            ]
            target_map[version] = [dep["package"] for dep in active if dep["kind"] == "required"]
        versions[package_id] = version_list
        entries[package_id] = entry_map
        active_deps[package_id] = dep_map
        required_targets[package_id] = target_map

    root_by_id = {root["package"]: root for root in roots}
    root_ids = [root["package"] for root in roots]
    domains = {}
    for package_id in packages:
        if package_id in root_by_id:
            root = root_by_id[package_id]
            domains[package_id] = [
                version for version in versions[package_id]
                if _fits(version, root.get("min"), root.get("max"))
            ]
        else:
            domains[package_id] = list(versions[package_id])

    return {
        "packages": packages,
        "order": order,
        "versions": versions,
        "active_deps": active_deps,
        "required_targets": required_targets,
        "root_ids": root_ids,
        "domains": domains,
    }


def _compatible(package, version, assigned, data):
    active_deps = data["active_deps"]
    fits = _fits
    for dep in active_deps[package][version]:
        target = dep["package"]
        if target in assigned and not fits(assigned[target], dep["min"], dep["max"]):
            return False
    for source, source_version in assigned.items():
        for dep in active_deps[source][source_version]:
            if dep["package"] == package and not fits(version, dep["min"], dep["max"]):
                return False
    return True


def _leaf_valid(assigned, closure, data):
    if set(assigned) != set(closure):
        return False
    active_deps = data["active_deps"]
    for package, version in assigned.items():
        for dep in active_deps[package][version]:
            target = dep["package"]
            if target not in assigned or not _fits(assigned[target], dep["min"], dep["max"]):
                return False
    return True


def _solve(request, roots, assess, stop_after_first):
    data = _prepare(request, roots)
    root_ids = data["root_ids"]
    domains = data["domains"]
    required_targets = data["required_targets"]
    packages = data["packages"]
    order = data["order"]

    # A root with no offered version inside its interval can never be satisfied.
    for package_id in root_ids:
        if not domains[package_id]:
            return {"feasible_count": 0, "selected": {}, "evaluation": None}

    found = 0
    best_selected = None
    best_evaluation = None
    best_changes = None
    best_freshness = -1

    class _Found(Exception):
        pass

    def expand(assigned, closure):
        changed = True
        while changed:
            changed = False
            for package in list(closure):
                if package not in assigned:
                    continue
                for target in required_targets[package][assigned[package]]:
                    if target not in closure:
                        closure.add(target)
                        changed = True

    def rec(assigned, closure):
        nonlocal found, best_selected, best_evaluation, best_changes, best_freshness
        expand(assigned, closure)

        unassigned = [package for package in closure if package not in assigned]
        if unassigned:
            # A fixed global order keeps every complete assignment unique.
            next_package = min(unassigned, key=lambda package: order[package])
            for version in domains[next_package]:
                if not _compatible(next_package, version, assigned, data):
                    continue
                assigned[next_package] = version
                rec(assigned, set(closure))
                del assigned[next_package]
                if stop_after_first and found:
                    return
            return

        if not _leaf_valid(assigned, closure, data):
            return
        selected = {package: list(version) for package, version in assigned.items()}
        evaluation = assess(roots, selected)
        if evaluation is None:
            return

        found += 1
        score = evaluation["score"]
        changes = score["changes"]
        freshness = score["freshness"]
        if best_selected is None or changes < best_changes or (changes == best_changes and freshness > best_freshness):
            best_selected = selected
            best_evaluation = evaluation
            best_changes = changes
            best_freshness = freshness

        if stop_after_first:
            raise _Found

    try:
        rec({}, set(root_ids))
    except _Found:
        pass

    if found == 0:
        return {"feasible_count": 0, "selected": {}, "evaluation": None}
    return {
        "feasible_count": found,
        "selected": best_selected,
        "evaluation": best_evaluation,
    }


def select_versions(request, roots, assess):
    """Return count, an optimal selection, and its assessor evaluation."""
    return _solve(request, roots, assess, False)


def has_feasible(request, roots, assess):
    """True when the exact root list admits at least one complete choice."""
    return _solve(request, roots, assess, True)["feasible_count"] > 0

from itertools import combinations

from runtime import build, read

from .selection_constraints import assess_selection
from .global_selection import select_versions, has_feasible


def _assess(request, roots, selected):
    return assess_selection(request, roots, selected)


def _minimal_root_conflict(request, roots, assess):
    root_rows = list(roots)
    for size in range(1, len(root_rows) + 1):
        for indices in combinations(range(len(root_rows)), size):
            subset = [root_rows[index] for index in indices]
            if not has_feasible(request, subset, assess):
                return sorted(root_rows[index]["package"] for index in indices)
    return []


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    roots = request["config"]["roots"]
    assess = lambda root_list, selected: _assess(request, root_list, selected)

    solution = select_versions(request, roots, assess)

    if solution["feasible_count"] > 0:
        selected = solution["selected"]
        evaluation = solution["evaluation"]
        return {
            "status": "ready",
            "selected": [
                {"package": package, "version": list(selected[package])}
                for package in sorted(selected)
            ],
            "active_dependencies": evaluation["active_dependencies"],
            "prior_deltas": evaluation["prior_deltas"],
            "score": evaluation["score"],
            "feasible_count": solution["feasible_count"],
            "minimal_root_conflict": [],
        }

    return {
        "status": "blocked",
        "selected": [],
        "active_dependencies": [],
        "prior_deltas": [],
        "score": None,
        "feasible_count": 0,
        "minimal_root_conflict": _minimal_root_conflict(request, roots, assess),
    }


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

