def fits(v,lo,hi):
    v=tuple(v); return (lo is None or tuple(lo)<=v) and (hi is None or v<tuple(hi))

def brute(req, roots):
    pkgs=[p['package'] for p in req['catalog']]
    vmap={p['package']:[v['version'] for v in p['versions']] for p in req['catalog']}
    domains=[]
    for p in pkgs:
        dom=[None]+[tuple(v) for v in vmap[p]]
        # root must not be None; brute can still skip but ok. We can leave.
        domains.append(dom)
    best=None; cnt=0
    for combo in itertools.product(*domains):
        sel={p:list(v) for p,v in zip(pkgs,combo) if v is not None}
        ev=assess_selection(req,roots,sel)
        if ev is not None:
            cnt+=1
            sc=ev['score']
            key=(sc['changes'],-sc['freshness'])
            if best is None or key<best[0]:
                best=(key,sel,ev)
    return cnt,best

def random_req(seed):
    rng=random.Random(seed)
    n=rng.randint(1,4)
    pkgs=[chr(65+i) for i in range(n)]
    catalog=[]
