                for q in pkgs:
                    if q==p: continue
                    if rng.random()<0.35:
                        kind=rng.choice(['required','peer'])
                        feature=rng.choice([None,'turbo','x',None,None])
                        lo=None
                        hi=None
                        if rng.random()<0.5:
                            # interval around some q version
                            qv=rng.choice(vmap[q])
                            lo=qv
                            hi=[qv[0]+1,0,0] if qv[0]<3 else None
                        deps.append({'package':q,'min':lo,'max':hi,'kind':kind,'feature':feature})
            req['catalog'][pi]['versions'].append({'version':v,'deps':deps})
    # roots subset with intervals random
    k=rng.randint(0,min(3,n))
    rp=rng.sample(pkgs,k)
    for p in rp:
        root={'package':p,'min':None,'max':None}
        if rng.random()<0.5:
            vv=rng.choice(vmap[p]); root['min']=vv
            if vv[0]<3: root['max']=[vv[0]+1,0,0]
        req['config']['roots'].append(root)
    # prior random for some
    for p in pkgs:
        if rng.random()<0.5:
            req['config']['prior'][p]=rng.choice(vmap[p])
    return req

