        for dep in active_deps[package][version]:
            target = dep["package"]
            if target == package:
                if not _fits(version, dep["min"], dep["max"]):
                    return False
            elif target in current and not _fits(current[target], dep["min"], dep["max"]):
                return False
        for source, source_version in current.items():
            for dep in active_deps[source][source_version]:
                if dep["package"] == package and not _fits(version, dep["min"], dep["max"]):
                    return False
        return True

