        local_best_changes = None
        local_best_freshness = -1
        local_best_assigned = None
        for changes, (component_freshness, witness) in combined.items():
            total_changes = base_changes + changes
            total_freshness = base_freshness + component_freshness
            if local_best_assigned is None or total_changes < local_best_changes or (
                total_changes == local_best_changes and total_freshness > local_best_freshness
            ):
                local_best_changes = total_changes
                local_best_freshness = total_freshness
