def select_versions(request, roots, assess):
    """Return count, an optimal selection, and its assessor evaluation."""
    return _solve(request, roots, assess, False)


def has_feasible(request, roots, assess):
    """True when the exact root list admits at least one complete choice."""
    return _solve(request, roots, assess, True)["feasible_count"] > 0

