ROOT = Path(__file__).resolve().parents[2]


class AssessSelectionTests(unittest.TestCase):
    def test_peer_does_not_pull_target_into_closure(self):
        request = {
            "config": {
                "roots": [{"package": "A", "min": None, "max": None}],
                "features": ["turbo"],
                "prior": {},
            },
            "catalog": [
                {
                    "package": "A",
                    "versions": [
                        {
                            "version": [1, 0, 0],
                            "deps": [
                                {
                                    "package": "B",
                                    "min": None,
                                    "max": None,
                                    "kind": "peer",
                                    "feature": "turbo",
                                }
                            ],
                        }
                    ],
                },
                {"package": "B", "versions": [{"version": [1, 0, 0], "deps": []}]},
            ],
        }
        roots = request["config"]["roots"]
        self.assertIsNone(assess_selection(request, roots, {"A": [1, 0, 0]}))
        self.assertIsNone(
            assess_selection(request, roots, {"A": [1, 0, 0], "B": [1, 0, 0]})
        )

        both_roots = roots + [{"package": "B", "min": None, "max": None}]
        evaluation = assess_selection(
            request, both_roots, {"A": [1, 0, 0], "B": [1, 0, 0]}
        )
        self.assertIsNotNone(evaluation)
        self.assertIn(
            {"source": "A", "target": "B", "kind": "peer", "feature": "turbo"},
            evaluation["active_dependencies"],
        )


class GlobalSelectionTests(unittest.TestCase):
    def test_min_changes_beats_higher_freshness(self):
        request = {
            "config": {
                "roots": [{"package": "A", "min": None, "max": None}],
                "features": [],
                "prior": {},
            },
            "catalog": [
                {
                    "package": "A",
                    "versions": [
                        {"version": [1, 0, 0], "deps": []},
                        {"version": [2, 0, 0], "deps": []},
                        {"version": [3, 0, 0], "deps": []},
                    ],
                }
            ],
        }

        def assess(roots, selected):
            version = selected.get("A")
            if len(selected) != 1 or version not in ([1, 0, 0], [2, 0, 0], [3, 0, 0]):
                return None
            changes = 0 if version == [1, 0, 0] else 1
            freshness = 100 * version[0] + 10 * version[1] + version[2]
            return {
                "active_dependencies": [],
                "prior_deltas": [],
                "score": {"changes": changes, "freshness": freshness},
            }

